document.addEventListener("DOMContentLoaded", function () {
  const logo = document.querySelector(".hero_home_logo-typo");
  const illus = document.querySelector(".hero_home_logo-illus");
  const list = document.querySelector(".hero_home_categories");
  const home = document.querySelector(".home");

  setTimeout(() => {
    logo.classList.add("slide-up");

    setTimeout(() => {
      list.classList.remove("hidden");
      list.classList.add("slide-in");

      // Vérifier si l'écran est inférieur à 921px
      if (window.innerWidth < 921) {
        illus.classList.add("slide-up");
        home.classList.add("visible");
      }
    }, 500);
  }, 2000);
});
